"""Generated by test-gen (standard) from docs/implementations/020-schema-format-cleanup-refactor-be.md §BE-5.
Regenerate: /test-gen standard docs/implementations/020-schema-format-cleanup-refactor-be.md

Layer isolation: imports only app/ + stdlib + pytest. No sibling-layer (DB/FE) imports,
no network, no real DB. Every test uses a fresh `tmp_path` as the storage root and
patches `app.core.storage.get_settings` directly (the module-level lru_cache on the
real `get_settings` is never touched). `get_storage.cache_clear()` runs before and
after every test so the per-bucket cache never leaks between tests.

Seam mocks: none — §7.1(b) (the Bucket enum + get_storage contract) is realized by
this unit, not assumed from a sibling layer.
"""

from __future__ import annotations

from pathlib import Path

import pytest

from app.core import storage as storage_module
from app.core.config import Settings
from app.core.storage import Bucket, LocalStorage, NasStorage, get_storage


@pytest.fixture(autouse=True)
def _clear_storage_cache() -> None:
    get_storage.cache_clear()
    yield
    get_storage.cache_clear()


def _settings(tmp_path: Path, **overrides: str | None) -> Settings:
    return Settings(storage_root=str(tmp_path), **overrides)  # type: ignore[arg-type]


def _patch_settings(monkeypatch: pytest.MonkeyPatch, settings: Settings) -> None:
    monkeypatch.setattr(storage_module, "get_settings", lambda: settings)


# --- Positive ------------------------------------------------------------------------


def test_get_storage_returns_local_storage_rooted_at_default_for_each_bucket(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    settings = _settings(tmp_path)
    _patch_settings(monkeypatch, settings)

    for bucket in Bucket:
        fs = get_storage(bucket)
        assert isinstance(fs, LocalStorage)
        expected_root = tmp_path / bucket.value
        assert fs._root == expected_root
        assert expected_root.is_dir()


def test_get_storage_override_wins_over_default(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    override_root = tmp_path / "custom_kyc_share"
    settings = _settings(tmp_path, storage_root_kyc=str(override_root))
    _patch_settings(monkeypatch, settings)

    fs = get_storage(Bucket.KYC)
    assert isinstance(fs, LocalStorage)
    assert fs._root == override_root
    assert override_root.is_dir()
    # A sibling bucket with no override still gets the default.
    marketing_fs = get_storage(Bucket.MARKETING)
    assert marketing_fs._root == tmp_path / "marketing"


def test_get_storage_cache_returns_same_instance_per_bucket(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _patch_settings(monkeypatch, _settings(tmp_path))

    first = get_storage(Bucket.REPORTS)
    second = get_storage(Bucket.REPORTS)
    assert first is second


def test_get_storage_different_bucket_returns_different_instance(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _patch_settings(monkeypatch, _settings(tmp_path))

    reports_fs = get_storage(Bucket.REPORTS)
    legal_fs = get_storage(Bucket.LEGAL)
    assert reports_fs is not legal_fs


# --- Negative ------------------------------------------------------------------------


def test_get_storage_with_no_argument_raises_type_error() -> None:
    with pytest.raises(TypeError):
        get_storage()  # type: ignore[call-arg]


def test_get_storage_nas_backend_returns_nas_storage_with_notimplemented_methods(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    _patch_settings(monkeypatch, _settings(tmp_path, storage_backend="nas"))

    fs = get_storage(Bucket.MARKETING)
    assert isinstance(fs, NasStorage)
    with pytest.raises(NotImplementedError):
        fs.open("whatever.pdf")
    with pytest.raises(NotImplementedError):
        fs.list("subdir")


def test_settings_no_longer_has_legal_docs_subdir_or_client_statements_subdir() -> None:
    settings = Settings()
    with pytest.raises(AttributeError):
        settings.legal_docs_subdir  # type: ignore[attr-defined]
    with pytest.raises(AttributeError):
        settings.client_statements_subdir  # type: ignore[attr-defined]


# --- Invariants ------------------------------------------------------------------------


def test_storage_module_imports_no_feature_package() -> None:
    source = Path(storage_module.__file__).read_text(encoding="utf-8")
    import_lines = [
        line.strip()
        for line in source.splitlines()
        if line.strip().startswith(("import ", "from "))
    ]
    assert import_lines, "expected at least one import statement"
    assert not any("app.libs" in line for line in import_lines)


def test_every_bucket_root_is_distinct(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _patch_settings(monkeypatch, _settings(tmp_path))

    roots = {bucket: get_storage(bucket)._root for bucket in Bucket}  # type: ignore[attr-defined]
    # 021 BE-0: count deliberately not hardcoded -- Bucket.CHAT made a literal 6 lie.
    # The invariant is that every bucket gets its OWN root, not how many there are.
    assert len(set(roots.values())) == len(Bucket)


def test_cache_clear_restores_clean_state(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    _patch_settings(monkeypatch, _settings(tmp_path))

    first = get_storage(Bucket.STATEMENTS)
    get_storage.cache_clear()
    second = get_storage(Bucket.STATEMENTS)
    assert first is not second


if __name__ == "__main__":
    import sys

    sys.exit(pytest.main([__file__, "-q"]))
